SELECT n.*, c.name as community_name, u.username as author_name FROM news n LEFT JOIN community c ON n.community_id = c.id LEFT JOIN user u ON n.author_id = u.id
AND n.title LIKE CONCAT('%', #{title}, '%') AND n.community_id = #{communityId} AND n.status = #{status}
ORDER BY n.create_time DESC

